// VehicleGrid.tsx
// Premium vehicle carousel for the landing page.
// Uses card-premium hover effects, glassmorphism navigation, and dot indicators.

import React, { useCallback, useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ChevronLeft, ChevronRight, Camera } from "lucide-react";
import { urlFor } from "../lib/sanity";
import { getVehicleRoute } from "../utils/routeHelper";

interface Vehicle {
  id: number;
  brand: string;
  model: string;
  year: number;
  images: string[];
  condition: "new" | "used";
  mileage?: number;
  fuel: string;
  _id?: string;
  priceUsd?: number;
}

// ─── Vehicle Card ─────────────────────────────────────────────────────────────

const VehicleCard: React.FC<{ vehicle: Vehicle }> = ({ vehicle }) => {
  const navigate = useNavigate();

  const imageUrl = vehicle.images?.[0]
    ? (vehicle as any).images[0]._type
      ? urlFor(vehicle.images[0]).width(600).url()
      : vehicle.images[0]
    : "/placeholder-car.jpg";

  const photoCount = vehicle.images?.length ?? 0;

  const formattedPrice = vehicle.priceUsd
    ? `USD $${vehicle.priceUsd.toLocaleString("en-US")}`
    : null;

  return (
    <div className="card-premium bg-white rounded-2xl overflow-hidden flex-shrink-0 min-w-[85vw] sm:min-w-[320px] sm:max-w-[340px]">
      {/* Image area */}
      <div className="relative w-full h-44 sm:h-56 overflow-hidden">
        <img
          src={imageUrl}
          alt={`${vehicle.brand} ${vehicle.model}`}
          className="card-image object-cover w-full h-full"
          loading="lazy"
        />

        {/* Subtle gradient overlay */}
        <div className="overlay-gradient-subtle absolute inset-0 pointer-events-none" />

        {/* Condition badge */}
        <span
          className={`absolute top-3 left-3 px-3 py-1 rounded-full text-xs font-bold ${
            vehicle.condition === "new"
              ? "bg-gradient-to-r from-red-600 to-red-500 text-white badge-glow"
              : "glass-dark text-white"
          }`}
        >
          {vehicle.condition === "new" ? "0 KM" : "Usado"}
        </span>

        {/* Photo count pill */}
        {photoCount > 0 && (
          <span className="absolute bottom-3 right-3 glass-dark text-white px-2.5 py-1 rounded-full text-xs font-medium flex items-center gap-1">
            <Camera size={12} />
            {photoCount}
          </span>
        )}
      </div>

      {/* Info area */}
      <div className="p-5 flex flex-col gap-3">
        <div>
          <h3 className="text-lg font-extrabold text-gray-900 truncate">
            {vehicle.brand} {vehicle.model}
          </h3>
          <p className="text-sm text-gray-500">Año: {vehicle.year}</p>
        </div>

        {formattedPrice && (
          <p className="text-lg font-bold text-red-600">{formattedPrice}</p>
        )}

        {/* Action buttons */}
        <div className="flex gap-2 mt-1">
          <button
            className="flex-1 px-4 py-2.5 bg-gray-900 text-white font-semibold rounded-xl hover:bg-red-600 transition-colors duration-200 text-sm"
            onClick={() => navigate(getVehicleRoute(vehicle))}
          >
            Ver detalle
          </button>
          <button
            className="flex-1 px-4 py-2.5 bg-green-600 text-white font-semibold rounded-xl hover:bg-green-700 transition-colors duration-200 text-sm"
            onClick={() => navigate(`/consultar?vehiculoId=${vehicle.id}`)}
          >
            Consultar
          </button>
        </div>
      </div>
    </div>
  );
};

// ─── Vehicle Grid (Carousel) ─────────────────────────────────────────────────

const VehicleGrid: React.FC<{ vehicles: Vehicle[] }> = ({ vehicles }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);

  // Track the currently visible card via scroll position
  const handleScroll = useCallback(() => {
    const container = scrollRef.current;
    if (!container) return;

    const cards = Array.from(container.children) as HTMLElement[];
    if (cards.length === 0) return;

    const viewport = container.clientWidth;
    const centerX = container.scrollLeft + viewport / 2;

    let closestIdx = 0;
    let closestDist = Infinity;

    cards.forEach((card, idx) => {
      const cardCenter = card.offsetLeft + card.clientWidth / 2;
      const dist = Math.abs(cardCenter - centerX);
      if (dist < closestDist) {
        closestDist = dist;
        closestIdx = idx;
      }
    });

    setActiveIndex(closestIdx);
  }, []);

  useEffect(() => {
    const container = scrollRef.current;
    if (!container) return;
    container.addEventListener("scroll", handleScroll, { passive: true });
    return () => container.removeEventListener("scroll", handleScroll);
  }, [handleScroll]);

  // Scroll to a specific card by index
  const scrollToIndex = useCallback((index: number) => {
    const container = scrollRef.current;
    if (!container) return;

    const cards = Array.from(container.children) as HTMLElement[];
    if (index < 0 || index >= cards.length) return;

    const targetCard = cards[index];
    const viewport = container.clientWidth;
    const targetCenter = targetCard.offsetLeft + targetCard.clientWidth / 2;
    const newScrollLeft = targetCenter - viewport / 2;

    container.scrollTo({ left: newScrollLeft, behavior: "smooth" });
  }, []);

  // Navigate one card left or right
  const scroll = useCallback(
    (direction: "left" | "right") => {
      const container = scrollRef.current;
      if (!container) return;

      const cards = Array.from(container.children) as HTMLElement[];
      if (cards.length === 0) return;

      const viewport = container.clientWidth;
      const centerX = container.scrollLeft + viewport / 2;

      let closestIdx = 0;
      let closestDist = Infinity;

      cards.forEach((card, idx) => {
        const cardCenter = card.offsetLeft + card.clientWidth / 2;
        const dist = Math.abs(cardCenter - centerX);
        if (dist < closestDist) {
          closestDist = dist;
          closestIdx = idx;
        }
      });

      const nextIdx =
        direction === "left"
          ? Math.max(closestIdx - 1, 0)
          : Math.min(closestIdx + 1, cards.length - 1);

      scrollToIndex(nextIdx);
    },
    [scrollToIndex]
  );

  return (
    <div className="relative w-full">
      {/* Carousel container */}
      <div
        ref={scrollRef}
        className="flex scroll-snap-x scrollbar-none carousel-fade-edges gap-6 py-8 px-4 overflow-x-auto"
      >
        {vehicles.map((vehicle) => (
          <div key={vehicle.id} className="snap-center">
            <VehicleCard vehicle={vehicle} />
          </div>
        ))}
      </div>

      {/* Navigation: Left — hidden on mobile, touch scroll is natural */}
      <button
        onClick={() => scroll("left")}
        className="hidden sm:flex absolute left-2 top-1/2 -translate-y-1/2 z-20 w-11 h-11 glass-card rounded-full shadow-lg items-center justify-center hover:scale-110 transition-transform duration-200 focus:outline-none"
        aria-label="Anterior"
      >
        <ChevronLeft className="w-5 h-5 text-gray-800" />
      </button>

      {/* Navigation: Right — hidden on mobile */}
      <button
        onClick={() => scroll("right")}
        className="hidden sm:flex absolute right-2 top-1/2 -translate-y-1/2 z-20 w-11 h-11 glass-card rounded-full shadow-lg items-center justify-center hover:scale-110 transition-transform duration-200 focus:outline-none"
        aria-label="Siguiente"
      >
        <ChevronRight className="w-5 h-5 text-gray-800" />
      </button>

      {/* Indicators — progress bar on mobile when many, dots on desktop */}
      {vehicles.length > 1 && (
        <div className="flex justify-center items-center gap-1.5 pb-4 px-4">
          {vehicles.length <= 8 ? (
            // Show dots when few vehicles
            vehicles.map((_, idx) => (
              <button
                key={idx}
                onClick={() => scrollToIndex(idx)}
                className={`w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full transition-all duration-300 focus:outline-none ${
                  idx === activeIndex
                    ? "bg-red-600 scale-125"
                    : "bg-gray-300"
                }`}
                aria-label={`Ir al vehículo ${idx + 1}`}
              />
            ))
          ) : (
            // Compact progress bar for many vehicles
            <div className="flex items-center gap-2 w-full max-w-[200px]">
              <span className="text-xs text-gray-400 font-medium tabular-nums">
                {activeIndex + 1}/{vehicles.length}
              </span>
              <div className="flex-1 h-1 bg-gray-200 rounded-full overflow-hidden">
                <div
                  className="h-full bg-red-600 rounded-full transition-all duration-300"
                  style={{ width: `${((activeIndex + 1) / vehicles.length) * 100}%` }}
                />
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default VehicleGrid;